		-- 이동속도 증가 lv5
		dlg_menu( "@90010226", "summer_event_Buff_operation(6)" )			
		-- 시전속도 증가 lv5
		dlg_menu( "@90010227", "summer_event_Buff_operation(7)" )				
	
	else
		-- 국가코드=16 즉 , 일본일 경우 2시간짜리 버프 지급
