			-- 시전속도 증가 lv5
			dlg_menu( "@90010227", "japan_summer_event_Buff_operation(7)" )				
		
		end -- if state_code == 16 then 
			
	--돌아가기
	dlg_menu( "@90010003", "NPC_Kores_summer_Event_contact()" )	

	-- 대화종료 
	dlg_menu( "@90010002", " " )
