function Warp_Halloween_to_City()
	if (gv('rx') == nil or gv('rx') == "") and (gv('ry') == nil or gv('ry') == "") then -- 해외
		warp(get_flag( "rx" ), get_flag( "ry" ))
	else -- 국내
		warp(gv( "rx" ), gv( "ry" ))
	end
	
end

