		dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
		delete_item( get_item_handle( 2010380 ), 50 )
		insert_item ( 690425, 1 )		-- 러브하트 펫 지급 한다.
		
	else 								-- 50개 이상이 안되는 모든 경우
		dlg_title( "@90996995" )
		dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
		
	end
		
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()

end





