-- 이벤트 수락 
function easter_event_agreed()

	-- 레시피를 받았나 확인
	local item_count = find_item ( 2010400 )
	item_handle = get_item_handle ( 2010400 )
	
	-- 레시피 보상을 받은 적 있는지 체크
	local q_flag0 = tonumber( get_flag( "q20" ) )

	if q_flag0 == nil then
		q_flag0 = 0
		set_flag( "q20", "0" )
	end
			
			-- 보상을 받은 적 있는지 체크
			-- 이미 보상을 받았으면 출력
	
			if q_flag0 >= 1 then
			      dlg_title( "@90999201" )		-- NPC 이름
	
			-- 레시피를 아직 못 받았을 때
			else
				dlg_title( "@90999201" )		-- NPC 이름
				insert_item ( 2010400, 1 )		-- 레시피를 건네 준다.(2010400)
				set_flag( "q20", "1" )
			end
	-- 다이얼로그 출력
	dlg_title( "@90999201" )		--NPC 이름 부활절 이벤트 뚜레쥬
	dlg_text( "@90999205" )			--NPC 대사

	dlg_menu( "@90010003", "NPC_Event_Easter_contact()" )

	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end


