-- 여름 이벤트 아이템을 받아 다른 지역에 있는 NPC에게 전달
-- 시간안에 아이템을 전달 (2분 기간제 설정)
-- 얼음주머니 : 첫번째 아이템
-- 빙수 : 2번째 아이템
-- 수박 잭오랜던 : 이벤트 완료 아이템

-- 씨엘 NPC

function NPC_Event_summergala_1_contact()		-- NPC 클릭하면 대화 메뉴 출력된다.

	-- 수박 잭오랜턴 보상을 받은 적 있는지 체크
	local q_flag0 = get_flag( "summer_item" )
	local icepocket_count = find_item( 2010687 )	-- 얼음주머니 확인
	local icewater_count = find_item( 2010688 )	-- 빙수 확인
		
	--플레그값 초기화 시켜 주기
		if q_flag0 == "" then
			q_flag0 = 0
		end

			-- 이미 보상을 받은 경우
				if q_flag0 >= 1 then 				--이미 보상을 받은 경우
				
					dlg_title( "@90999330" )			--NPC 이름
					dlg_text( "@90999347" )		--NPC 대사
					dlg_menu( "@90010002", " " )		--대화종료
					dlg_show()

			-- 얼음 주머니가 있는 경우
				elseif icepocket_count >=1 or icewater_count >=1 then
					dlg_title( "@90999330" )			--NPC 이름
					dlg_text( "@90999346" )		--NPC 대사
					dlg_menu( "@90010002", " " )		--대화종료
					dlg_show()
				
			-- 수박 잭오랜턴을 아직 못 받았을 때
				else
					dlg_title( "@90999330" )			--NPC 이름
					dlg_text( "@90999331" )		--NPC 대사
					dlg_menu( "@90999332", "summergala_agreed()" )		--이벤트 수락 : 도와준다
					dlg_menu( "@90010002", " " )		--대화종료
					dlg_show()	
					
				end	
end

-- 이벤트 수락

function summergala_agreed()
	
		dlg_title( "@90999330" )				--NPC 이름
		dlg_text( "@90999333" )			--NPC 대사
		dlg_menu( "@90999335", "summergala_receive_icepocket()" )		--얼음주머니를 받는다
		dlg_menu( "@90010002", " " )		--대화종료
		dlg_show()

end

