	function Independence_event_receive()
	
			local q_flag0 = get_flag( "Independence_item" )
			if q_flag0 == "" then
			q_flag0 = 0
			end
		
		if q_flag0 >= 1 then 
		dlg_text( "@90999448" )	--NPC대사
