-- 엔젤 1승 버프	
function Angel_nomal_buff_1v_operation( magic_set )

	-- 버프 7종 받아오기
	local state_level_1 = get_state_level( 1055 )
	local state_level_2 = get_state_level( 1053 )
	local state_level_3 = get_state_level( 1054 )
	local state_level_4 = get_state_level( 1056 )
	
	if magic_set == 1 and state_level_1 == 0 then
		add_state( 1011, 3, 540000 ) -- 공속lv3 증가
		Angel_nomal_buff_1v()	
		return
	else
		dlg_title( "@90999451" )	
		dlg_text( "@90999533" )
	end		
	
	if magic_set == 2 and state_level_2 == 0 then
			add_state( 1009, 3, 540000 ) -- 방어력lv3 증가
		Angel_nomal_buff_1v()	
		return
	else
		dlg_title( "@90999451" )	
		dlg_text( "@90999533" )
	end		
	
	if magic_set == 3 and state_level_3 == 0 then
			add_state( 1010, 3, 540000 ) -- 마법방어력lv3 증가
		Angel_nomal_buff_1v()	
		return
	else
		dlg_title( "@90999451" )	
		dlg_text( "@90999533" )
	end
	
	if magic_set == 4 and state_level_4 == 0 then
			add_state( 1012, 3, 540000 ) -- 시전속도lv3 증가
		Angel_nomal_buff_1v()	
		return
	else
		dlg_title( "@90999451" )	
		dlg_text( "@90999533" )
	end
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end	
	
