-- 구해온것을 준다.
function EU_09_autumn_event_give()
	
	local leaf_count = find_item( 2010901 )	-- 나뮈르의 잎 확인
	local bark_count = find_item( 2010902 )	-- 나뮈르의 껍질 확인
	local seed_count = find_item( 2010903 )	-- 나뮈르의 씨앗 확인
	
	if leaf_count >= 20 and bark_count >= 10 and seed_count >= 3 then
	
	dlg_title( "@90999595" )	--npc이름		
	dlg_text( "@90999605" )	--npc 기본 대사
		
	insert_item ( 2010904, 1 )			-- 나뮈르의 새싹을 준다.
	delete_item( get_item_handle( 2010901 ), 20 )	-- 나뮈르의 잎 회수
	delete_item( get_item_handle( 2010902 ), 10 )	-- 나뮈르의 껍질 회수
	delete_item( get_item_handle( 2010903 ), 3 )	-- 나뮈르의 씨앗 회수
	
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()

	else
	dlg_title( "@90999595" )	--npc이름		
	dlg_text( "@90999604" )	--npc 기본 대사

	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
	end

end


