---------------------------------------------------------------------------------------

function NPC_event_09_christmas_start()
	dlg_title( "@90999555" )
	dlg_text( "@90999556" )
	dlg_menu( "@90999859", "event_09_christmas_receive()" )	--크리스마스 선물 상자 받기
	dlg_menu( "@90010002", "" )	--대화 종료
	dlg_show()
end

function event_09_christmas_receive()
	local level = get_value( "level" )	--레벨 확인
	local q_flag1 = get_flag( "09_christmas" )
	if q_flag1 == nil or q_flag1 == "" then
	q_flag1 = 0
	end
	
	if level >= 15 then
		if q_flag1 >= 1 then
			dlg_title( "@90999555" )
			dlg_text( "@90999860" )	--이미 선물 상자를 받은 경우
			dlg_menu( "@90010002", "" )	--대화 종료
			dlg_show()
		else
			dlg_title( "@90999555" )
			dlg_text( "@90999861" )
			insert_item( 2011111, 1 )	--크리스 마스 선물 상자 지급
			set_flag( "09_christmas", "1")
			dlg_menu( "@90010002", "" )	--대화 종료
			dlg_show()
		end
	else
		dlg_title( "@90999555" )
		dlg_text( "@90999862" )	--레벨이 15미만인 경우
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()	
end
end

