function NPE_event_WD_2010_xmas_1day_contact()
	local q_flag0 = get_flag( "2010xmas_flag" )
	--값이 없는(공백) 플래그 값 0으로 만들어 주기
	if q_flag0 == "" then
		q_flag0 = 0
