function NPC_Event_yut_younghee()
	local npc_name = "@"..get_npc_type().."|@"..get_npc_name()
	dlg_title( npc_name)
	
	dlg_text( "@90610333" )	--대사 (인사)
	dlg_menu( "@90610334", "Event_yuttable_give()" )	--윷판 받기
	dlg_menu( "@90610335", "Event_yut_give()" )	--윷놀이 받기
	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
end

function Event_yuttable_give()
	local npc_name = "@"..get_npc_type().."|@"..get_npc_name()
	dlg_title(npc_name)
	
	local item_id = 2012164	
	local yuttable = 0
	
	for i = 1, 31 do
		if find_item( item_id ) >= 1 then
			yuttable = 1
			break
		end
		item_id = item_id + 1
	end
	
	if yuttable == 1 then
		dlg_text( "@90610336" )
	else
		dlg_text( "@90610339" )
		insert_item( 2012164, 1 )	--윷 판<2011년 구정 이벤트>
	end
	
	dlg_menu( "@90010002", " " )	--대화 종료
end

function Event_yut_give()
	local state_code = get_local_info()
	local npc_name = "@"..get_npc_type().."|@"..get_npc_name()
	dlg_title(npc_name)
	
	local q_flag
	if state_code == 1 then
		q_flag = get_account_flag( "yut2017" )
	else
		q_flag = get_flag( "yut2017" )
	end
	
	if q_flag == "" or q_flag == nil then
		q_flag = 0
	end
	
	if q_flag < 1 then -- 안받았을 경우	
		dlg_text( "@90610338" )
		insert_item( 2012157, 1 )	--윷 놀이<2011년 구정 이벤트>
		if state_code == 1 then
			set_account_flag( "yut2017", "1")	
		else	
			set_flag( "yut2017", "1")
		end
	else	
		dlg_text( "@90610337" )	--대사 (아이템을 다시 받으려고 시도한 경우)
	end
	
	dlg_menu( "@90010002", "" )	--대화 종료
	dlg_show()	
end

