function NPC_Event_2011_Epic7_3_Update_box_contact()
	
	local current_time = get_os_date( "%Y-%m-%d %H:%M:%S" )
	local current_day = 0
	local local_flag = get_env( "game.local_flag" )

	if local_flag == 4 then ------------------------------------------------------------------------------미국
		
	day1_begin_time = '2011-11-23 18:00:00'	--1차 시작
	day2_begin_time = '2011-11-24 18:00:00'	--3차 시작
	day3_begin_time = '2011-11-25 18:00:00'	--4차 시작
	day4_begin_time = '2011-11-26 18:00:00'	--5차 시작
