function Epic7_3_Update_event_1day()

	local q_flag1 = get_flag( "Epic7_3_Update_box_get" )
	if q_flag1 == "" then
		q_flag1 = 0
	end
	
	dlg_title( "@90604919" )	--NPC 이름 (선물 상자 지급 NPC 마테오)
	
	if q_flag1 < 1 then
		dlg_text( "@90604921" )	--기본 대사
		dlg_menu( "@90604922", "NPC_Event_2011_Epic7_3_Update_box_1_day()" )	--랜덤 박스 받기
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
	else
		dlg_text( "@90604923" )	--이미 받은 사람
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
	end
end

