function NPC_Event_2011_RU_NIKITA_20th()
	dlg_title( "@90999884" )	--NPC 이름 (이벤트 NPC 빈센트)
	dlg_text( "@90604929" )	--대사 (인사)
	
	if find_item ( 2013858 ) >= 1 then
		dlg_menu( "@90604931", "Event_2017_RU_NIKITA_26th_exchange(2013858, 2012448, 90604935, 90604933)" )	--"ON"카드 계수기로 교환
		dlg_menu( "@90604930", "Event_2017_RU_NIKITA_26th_exchange(2013858, 2012470, 90604932, 90604933)" )	--"ON"카드 선물 상자A로 교환
	end
	if find_item ( 2013845 ) >= 1 then
		dlg_menu( "@90604936", "Event_2017_RU_NIKITA_26th_exchange(2013845, 2012471, 90604941, 90604945)" )	--계수기23 선물 상자 B로 교환
	end
	if find_item ( 2013846 ) >= 1 then
		dlg_menu( "@90604937", "Event_2017_RU_NIKITA_26th_exchange(2013846, 2012471, 90604942, 90604945)" )	--계수기24 선물 상자 B로 교환
	end
	if find_item ( 2013847 ) >= 1 then
		dlg_menu( "@90604938", "Event_2017_RU_NIKITA_26th_exchange(2013847, 2012471, 90604943, 90604945)" )	--계수기25 선물 상자 B로 교환
	end
	if find_item ( 2013848 ) >= 1 then
		dlg_menu( "@90604939", "Event_2017_RU_NIKITA_26th_exchange(2013848, 2012471, 90604944, 90604945)" )	--계수기26 선물 상자 B로 교환
	end
	if find_item ( 2013901 ) >= 1 then
		dlg_menu( "@90604934", "Event_2017_RU_NIKITA_26th_exchange(2013901, 2012472, 90604940, 90604945)" )	--계수기27 선물 상자 C로 교환
	end
	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
end

function Event_2017_RU_NIKITA_26th_exchange(need_item, get_item, dlg_id, dlg_id1)
	dlg_title( "@90999884" )	--NPC 이름
	
	if 	find_item ( need_item ) >= 1 then
		dlg_text( "@"..dlg_id )	--대사 (ON 카드를 소지한 경우)
		insert_item ( get_item, 1 )	-- 선물상자 A 지급
		delete_item( get_item_handle( need_item ), 1 )	--ON 카드 1개 삭제		
	else
		dlg_text( "@"..dlg_id1 )	--대사 (ON카드가 없는 경우)
	end
	
	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
end

