-----------------------------------------------------------------------------------------------루돌프
function NPC_Event_2011_xmas_event_rudolph_contact()
	
	dlg_title( "@90605062" )	--NPC 이름 (행복을 주는 순록)
	
	local local_flag = get_env( "game.local_flag" )
	local xmas_begin_time = 1481583600 --get_os_second('2016-12-13 08:00:00') --이벤트 시작 날짜	
	local xmas_event_day = math.floor((get_os_time() - xmas_begin_time)/86400) + 1 -- 이벤트 일차
		
	local q_flag1 = get_flag( "xmas_2016_event_coupon_get" )
	if q_flag1 == "" then
		q_flag1 = 0
	end
	
	if q_flag1 < 15 and q_flag1 < xmas_event_day then
		dlg_text( "@90605064" )	--기본 대사
		dlg_menu( "@90605065", "xmas_2016_event_coupon()" ) --쿠폰 받기
	else
		dlg_text( "@90605067" )	--이미 받은 사람
	end
	
	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
end

function xmas_2016_event_coupon()
	dlg_title( "@90605062" )	--NPC 이름 (행복을 주는 순록)
	dlg_text( "@90604924" )	--대사
	local xmas_begin_time = 1481583600 --get_os_second('2016-11-29 11:00:00') --이벤트 시작 날짜		
	local xmas_event_day = math.floor((get_os_time() - xmas_begin_time)/86400) + 1 -- 이벤트 일차
	insert_item( 2012521, 1 )	--선물 쿠폰
	
	set_flag( "xmas_2016_event_coupon_get", xmas_event_day)
	dlg_menu( "@90010002", "" )	--대화 종료
	dlg_show()	
end

