function AE_request_2012_01_event_10000lak_exchange()
		
	--라크 소지량 체크
	local temp_lak
	player_lak = gv("chaos")
	
	--은 도금 상자 지급 확인
	
		if player_lak >= 10000 then
		temp_lak = player_lak - 10000
	
		dlg_title( "@90605099" )
		dlg_text( "@90605105" )
		insert_item ( 2012598, 1 )	-- 은 도금 카드 상자 1개 지급
		sv("chaos", temp_lak )	-- 라크를 깐다.
		update_gold_chaos()
		dlg_menu( "@90010003", "AE_request_2012_01_event_contact()" )		--처음으로	
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
		else
		dlg_title( "@90605099" )
		dlg_text( "@90605106" )
		dlg_menu( "@90010003", "AE_request_2012_01_event_contact()" )		--처음으로	
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
		end
	end

