function event_2012_kor_update_buff()
local level = get_value( "level" )	--레벨 체크
-- 버프 3종 받아오기 
local state_level_1 = get_state_level( 1510 )		-- 이동속도 증가 버프
local state_level_2 = get_state_level( 4003 )		-- 스태미너 세이버 버프
local state_level_3 = get_state_level( 145522 )		-- 주인에 헌신 버프

	dlg_title( "@91002076" )	--NPC 이름 (이벤트 NPC 빈센트)

	if level <= 100 then
	dlg_text( "@90605145" )	--대사	
		if state_level_1 <= 20 and state_level_2 <= 2 and state_level_3 <= 2 then	--이 부분은 해당 버프가 걸려 있지 않다면 정해진 버프를 걸어준다는 조건이다.
		add_state( 1510, 20, 720000 ) -- 이동속도 증가, lv20, 2시간
		add_state( 4003, 1, 720000 ) -- 스태미너 세이버, lv1, 2시간
		add_state( 145522, 1, 720000 ) -- 주인에 헌신, lv1, 2시간
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
		else
		dlg_text( "@90605146" )	--대사	
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
		end
	else
	dlg_text( "@90605147" )	--대사	
	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
	end
end


