			set_env("game.party_exp_rate_6",2.6) 		--실 경험치를 받는 파티원이 8명일 때 적용되는 보너스 계수 
		end
	else
		set_env("game.party_exp_rate_0",1) 	--이벤트 안함
		set_env("game.party_exp_rate_1",1) 	--이벤트 안함
		set_env("game.party_exp_rate_2",1) 	--이벤트 안함
		set_env("game.party_exp_rate_3",1) 	--이벤트 안함
		set_env("game.party_exp_rate_4",1) 	--이벤트 안함
		set_env("game.party_exp_rate_5",1) 	--이벤트 안함
		set_env("game.party_exp_rate_6",1) 	--이벤트 안함
		
	end
end

