function event_2015_xmas_give(item)
	dlg_title( "@91002043" )		--NPC 이름
	
	item_count = find_item(item)
	
	if item == 2013549 then 
		if item_count >= 3000 then
			dlg_text( "@90610154" )			--NPC 장난감 부품 조건 만족
			delete_item( get_item_handle( 2013549 ), 3000 )
			insert_item( 2016075, 1 )
		else
			dlg_text( "@90610155" )			--NPC 장난감 부품 조건 불만족
		end
	else
		if item_count >= 1 then
			dlg_text( "@90610156" )			--NPC 인형 조건 만족
			delete_item( get_item_handle( item ), 1 )
			insert_item( 2016076, 1 )
		else
			dlg_text( "@90610157" )			--NPC 인형 조건 불만족
		end
	end
	dlg_menu( "@90010003", "NPC_event_2015_xmas_contact()" )	--처음으로
	dlg_menu( "@91002046", " " )	--대화 창을 닫는다.
	dlg_show()
end
