function NPC_2014_Black_Market_event_change_gift(num) -- 메뉴3-1, 3-2의 교환 로직

	dlg_title( "@90606270" )

	local gift_item_code
	local need_lak
	
	if num == 1 then
		gift_item_code = 2013440 -- 한손 장검
		need_lak = 5500
	elseif num == 2 then
		gift_item_code = 2013439 -- 양손 장검
		need_lak = 11000
	elseif num == 3 then
		gift_item_code = 2013438 -- 단검
		need_lak = 5500
	elseif num == 4 then
		gift_item_code = 2013431 -- 양손 창
		need_lak = 11000
	elseif num == 5 then
		gift_item_code = 2013432 -- 한손 도끼
		need_lak = 5500
	elseif num == 6 then
		gift_item_code = 2013433 -- 양손 도끼
		need_lak = 11000
	elseif num == 7 then
		gift_item_code = 2013434 -- 한손 메이스
		need_lak = 5500
	elseif num == 8 then
		gift_item_code = 2013435 -- 양손 메이스
		need_lak = 11000
	elseif num == 9 then
		gift_item_code = 2013441 -- 대궁
		need_lak = 11000
	elseif num == 10 then
		gift_item_code = 2013442 -- 석궁
		need_lak = 11000
	elseif num == 11 then
		gift_item_code = 2013436 -- 한손 지팡이
		need_lak = 5500
	elseif num == 12 then
		gift_item_code = 2013437 -- 양손 지팡이
		need_lak = 11000
	elseif num == 13 then
		gift_item_code = 2013443 -- 공용 방패
		need_lak = 5500
	elseif num == 14 then
		gift_item_code = 2013444 -- 마법 방패
		need_lak = 5500
	elseif num == 15 then
		gift_item_code = -2001195 -- 모자
		need_lak = 500
	elseif num == 16 then
		gift_item_code = -2001200 -- 부츠
		need_lak = 500
	elseif num == 17 then
		gift_item_code = -2001205 -- 장갑
		need_lak = 500
	elseif num == 18 then
		gift_item_code = -2001210 -- 의상
		need_lak = 500
	end
	
	local temp_lak
	local player_lak
	
	player_lak = gv("chaos")
		
	if need_lak == player_lak or need_lak < player_lak then
		
		temp_lak = player_lak - need_lak
		
		dlg_text( "@90606281" ) -- 교환 완료
		insert_item( gift_item_code, 1 )	
		sv("chaos", temp_lak )
	
	else
	
		dlg_text( "@90606282" ) -- 부족해
	
	end	
	
	dlg_menu( "@90010003", "NPC_2014_Black_Market_event_change_gift_index()" )	--전단계로
	dlg_menu( "@90605911", "NPC_2014_Black_Market_event_contact()" )	--처음으로
	dlg_menu( "@90010002", " " )	--대화 종료
	
	dlg_show()

end

function Buff_9_1_event_monster_death() 

