function NPC_2013_christmas_event_change_gift(num) -- 메뉴3-1, 3-2의 교환 로직

	dlg_title( "@90605896" )

	local gift_item_code
	local need_ticket
	
	if num == 1 then
		gift_item_code = 2011150 -- 변조된 조각 랜덤상자 <28일>
		need_ticket = 1
	elseif num == 2 then
		gift_item_code = 2012867 -- 점토열쇠 랜덤박스
		need_ticket = 4
	elseif num == 3 then
		gift_item_code = 2012818 -- 축복받은 카벙클 상자 <3일>
		need_ticket = 10
	elseif num == 4 then
		gift_item_code = 3800282 -- 축복받은 크리처 상자
		need_ticket = 20
	elseif num == 5 then
		gift_item_code = 540117 -- 눈사람 빈 카드
		need_ticket = 50
	elseif num == 6 then
		gift_item_code = 2013537 -- 눈사람 가면 <60일>
		need_ticket = 50
	elseif num == 7 then
		gift_item_code = 2013538 -- 루돌프 사슴 코  <60일>
		need_ticket = 50
	elseif num == 8 then
		gift_item_code = 2013539 -- 산타 수염 <60일>
		need_ticket = 50
	elseif num == 9 then
		gift_item_code = 2013540 -- 산타 의상 <60일>
		need_ticket = 50
	elseif num == 10 then
		gift_item_code = 2013541 -- 크리스마스 망토 <60일>
		need_ticket = 50
	elseif num == 11 then
		gift_item_code = 2013542 -- 산타 신발 <60일>
		need_ticket = 50
	elseif num == 12 then
		gift_item_code = 2013543 -- 방울니트 모자 <60일>
		need_ticket = 50
	elseif num == 13 then
		gift_item_code = 2013544 -- 벙어리 장갑 <60일>
		need_ticket = 50
	elseif num == 14 then
		gift_item_code = 3800275 -- 다크메이지 꾸미기 셋트 랜덤 상자
		need_ticket = 100
	elseif num == 15 then
		gift_item_code = 2013545 -- 화려한 꾸미기 코스튬 랜덤 박스
		need_ticket = 100
	end
	
	local ticket = 2902195
	local ticket_count = find_item(ticket)
	
	if need_ticket == ticket_count or need_ticket < ticket_count then
		
		dlg_text( "@90605907" ) -- 교환 완료
		insert_item( gift_item_code, 1 )	
		delete_item( get_item_handle(ticket), need_ticket )
	
	else
	
		dlg_text( "@90605908" ) -- 상품권이 부족해
	
	end	
	
	dlg_menu( "@90010003", "NPC_2013_christmas_event_change_gift_index()" )	--전단계로
	dlg_menu( "@90605911", "NPC_2013_christmas_event_contact()" )	--처음으로
	dlg_menu( "@90010002", " " )	--대화 종료
	
	dlg_show()

end

