	dlg_title( title ) -- 심술쟁이 요정
	dlg_text( "@90606338" ) -- 심술쟁이 요정 대사
	
	dlg_menu( "@90606339", "NPC_Event_2014_christmas_pixie(" .. get_flag( "2016_christmas_team" ) .. ", '" .. title .. "', '@90606340')" ) -- 메뉴 1 : 도와주기
	
    dlg_menu( "@90606341", "NPC_Event_2014_christmas_pixie_toygive('" .. title .. "')" )	-- 장난감 건네기

	dlg_menu( "@90010003", "NPC_Event_2014_christmas_pixie(" .. get_flag( "2016_christmas_team" ) .. ", '" .. title .. "')" ) -- 돌아가기
	dlg_menu( "@90010002", " " ) -- 대화 종료
	
