function Valentine_2016_DiamondRing_Exchange_Done( change_num )

	local diamond_num = find_item ( 2013572 )	-- 다이아몬드 수량
	local diamondring_num = change_num			-- 다이아 반지 수량	
	
	if change_num == 0 then		--전부교환 선택 시
		diamondring_num = math.floor(diamond_num / 10)		-- 다이아 반지 수량
	end
	
	local need_diamond_num = diamondring_num*10		--	필요 다이아몬드		
		
	dlg_title( "@90606388" )
	
	if diamond_num >= need_diamond_num then
		insert_item( 2013573, diamondring_num )
		delete_item( get_item_handle( 2013572 ), need_diamond_num )
		dlg_text( "@90606407" )	-- 다이아몬드 교환 성공 대사
	else		
		dlg_text( "@90610190" )	-- 교환할 아이템이 부족한 경우
	end
	
	dlg_menu( "@90010003", "NPC_Event_2016_Valentine_qupid()" )	-- 돌아가기
	dlg_menu( "@90010002", " " )	-- 대화 종료
	dlg_show()
end
