	dlg_title( npc_name)

	if find_item( 2016105 ) >= 1 then -- 송편 재료 상자가 1개 이상 있을 경우
	
		dlg_text( "@90610290" )	-- 만들기 선택 시 대사, 몇개 만들거니?
		if find_item( 2016105 ) >= 1 then
			dlg_menu( "@90610291\v#@number@#\v1", "NPC_Event_2016_chusuk_Jill_songpyun_making(1)" )	-- 송편 1개 만들기
		end		
		if find_item( 2016105 ) >= 10 then
			dlg_menu( "@90610291\v#@number@#\v10", "NPC_Event_2016_chusuk_Jill_songpyun_making(10)" )	-- 송편 10개 만들기
		end
		if find_item( 2016105 ) >= 100 then
			dlg_menu( "@90610291\v#@number@#\v100", "NPC_Event_2016_chusuk_Jill_songpyun_making(100)" )	-- 송편 100개 만들기
		end
	
	else -- 송편 재료 상자가 없을 경우
	
