function RUnewyear_item_give(num)
	local npc_name = "@"..get_npc_type().."|@"..get_npc_name()	
	dlg_title(npc_name)	
	
	pdata =	{ -- item_id,	count, ticket,
				2011573, 1, 125, 	--라펠즈 컵 기념 반지 100일
				690341, 3, 10, 	--공격의 루나칩 1시간<1시간>
				960006, 1, 25, 	--7랭크 축복받은 안정화의 가루<잠금용>
				810321, 3, 75, 	--평온함의 날카로움(2)
				810322, 3, 75, 	--평온함의 마도사(2)
				810324, 3, 75, 	--평온함의 사냥꾼(2)
				491006, 1, 50, 	--라일리의 키트<벨트 슬롯 이전>
				700402, 1, 25, 	--고대의 큐브-스킬
			}
	
	local item_id = pdata[1+(num-1)*3]
	local item_count = pdata[2+(num-1)*3]
	local need_ticket_count = pdata[3+(num-1)*3]
	local ticket_count = find_item(2016122)
	
	if ticket_count < need_ticket_count then
		dlg_text( "@90610330" ) -- 당근 주스 부족
	else
		dlg_text( "@90610331" ) -- 교환 완료
		delete_item ( get_item_handle ( 2016122 ), need_ticket_count )
		insert_item ( item_id, item_count )
	end
	
	dlg_menu( "@90010003", "NPC_event_2017_RUnewyear_contact()" ) -- 돌아가기
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end
