	end
	
	private_notice( sconv( "@90610571", "#@arc_total@#", get_global_variable("arc_total"), "#@player_name@#", get_global_variable("US11Name"), "#@donation_amount@#", get_global_variable("US11Amount"), "#@personal_amount@#", get_flag ( "US11Count" ) ) )
	
	return
end

