	if team == 1 then -- Rebels
	
		dlg_text( "@90610583" )
	
	elseif team == 2 then -- Loyalists
		
		dlg_text( "@90610584" )
		
	end
	
	set_account_flag( "2017ChristmasClaim", 1 )
	insert_item( item, 1 )
	
	dlg_menu( "@90010002", " " ) --Goodbye
	dlg_show()
end

