function 	select_number_value_4(select,parray)
	local array_size = table.getn(parray)/4
	for i=1, array_size do
		local base = 1+(i-1)*4
		if select < parray[base] then
			return {parray[base+1], parray[base+2], parray[base+3]}
		end
	end
	return 0
end

